INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('1ro', 'Lenguas Extranjeras (Francés)', 'BC1', 'IL-1', 'Responde de forma adecuada a preguntas e indicaciones, a partir de la escucha de discursos y lectura de textos muy breves y sencillos cuya intención es saludar, despedirse, interactuar en el aula, presentarse y presentar a otras personas, referirse a actividades cotidianas, describir e indicar la ubicación, siempre que se le hable de forma muy pausada y clara, y se le repita o permita releer y rectificar en caso de que así lo requiera.'),
('1ro', 'Lenguas Extranjeras (Francés)', 'BC1', 'IL-2', 'Produce oralmente, aunque con muchas pausas y reformulaciones, discursos muy breves y sencillos, con la intención de saludar, despedirse, interactuar en el aula, presentarse y presentar otras personas, referirse a actividades cotidianas, describir e indicar la ubicación, utilizando un repertorio muy limitado de frases y oraciones aprendidas que el oyente puede comprender, aunque con cierto esfuerzo.'),
('1ro', 'Lenguas Extranjeras (Francés)', 'BC1', 'IL-3', 'Escribe textos muy breves y sencillos, utilizando un repertorio aprendido de frases y oraciones aisladas, con el propósito de saludar, despedirse, interactuar en el aula, presentarse y presentar otras personas, referirse a actividades cotidianas, describir e indicar la ubicación, aunque con errores gramaticales básicos.'),

